        "\n",
        "# Create a DataFrame for px.bar\n",
        "df_label_counts = label_counts.to_frame().reset_index()  # Convert Series to DataFrame\n",
        "df_label_counts.columns = ['Label', 'Count'] # Rename columns for clarity\n",
        "\n",
        "fig = px.bar(\n",
